// `@fx/wire` — hand-written declaration copy of
// `fixtures/multi-repo-contracts/shared/wire/src/index.ts`.
//
// The fixture must resolve without an install, so every repository that imports
// the shared package carries its own copy under `node_modules/@fx/wire`. The
